refentry.refsect1:
&reftitle.description;
public boolYaf_Route_Regex::route Yaf_Request_Abstractrequest
Enruta una petición entrante.

&reftitle.parameters;


  request


    La instancia de Yaf_Request_Abstract a enrutar.

  &reftitle.examples;

   Ejemplo de Yaf_Route_Regex::route


<?php
/* se supone que el URI de la petición es "/product/php-book" */
$request = new Yaf_Request_Http("/product/php-book");

$route = new Yaf_Route_Regex(
    "#^/product/([^/]+)/?$#", // match a URI leading "/product"
    array(
        'controller' => "product", // route to the product controller
    ),
    array(
        1 => "name", // $request->getParam("name") will be "php-book"
    )
);

var_dump($route->route($request));

var_dump($request->getControllerName());
var_dump($request->getParam("name"));
?>


   &example.outputs.similar;


bool(true)
string(7) "product"
string(8) "php-book"
